#!/usr/bin/env python3
"""Batch-test themes.toml values: for each (label, toml_content) launch the TUI
and report whether it errored (and the error text) or started OK."""
import os, sys, shutil, time, subprocess, json

sys.path.insert(0, "/workspace/explore")


def sh(*a):
    return subprocess.run(a, capture_output=True, text=True)


def run_case(sess, home, content, cols=120, rows=40, wait=1.0):
    if os.path.isdir(home):
        shutil.rmtree(home)
    cfg = os.path.join(home, ".config", "tui-journal")
    os.makedirs(cfg, exist_ok=True)
    with open(os.path.join(cfg, "themes.toml"), "w") as f:
        f.write(content)
    sh("tmux", "kill-session", "-t", sess)
    envs = {"HOME": home, "TERM": "xterm-256color",
            "XDG_CONFIG_HOME": os.path.join(home, ".config")}
    pre = " ".join(f"{k}={v!r}" for k, v in envs.items())
    cmd = f"env {pre} /workspace/executable; echo __TJEXIT_$?__; sleep 600"
    sh("tmux", "new-session", "-d", "-s", sess, "-x", str(cols), "-y", str(rows), cmd)
    time.sleep(wait)
    out = sh("tmux", "capture-pane", "-p", "-t", sess).stdout
    sh("tmux", "kill-session", "-t", sess)
    shutil.rmtree(home, ignore_errors=True)
    return out


def classify(out):
    if "__TJEXIT_" in out:
        code = out.split("__TJEXIT_")[1].split("__")[0]
        body = out.split("__TJEXIT_")[0].rstrip("\n")
        return ("EXIT" + code, body)
    if "Journals" in out:
        return ("RUNNING", "")
    return ("OTHER", out.rstrip("\n"))


def main():
    spec = json.load(open(sys.argv[1]))
    sess_base = sys.argv[2]
    for i, (label, content) in enumerate(spec):
        out = run_case(f"{sess_base}_{i}", f"/tmp/h_{sess_base}_{i}", content)
        st, body = classify(out)
        print("#" * 70)
        print(f"CASE: {label}")
        print(f"CONTENT: {content!r}")
        print(f"STATUS: {st}")
        if body:
            print("OUTPUT:")
            print(body)
        sys.stdout.flush()


if __name__ == "__main__":
    main()
#!/usr/bin/env python3
"""Helper for the themes exploration area: set up a HOME with a themes file,
launch the TUI, send keys, print captures."""
import os, sys, shutil, time, argparse
sys.path.insert(0, "/workspace/explore")
from tj import Tj, sh


def setup_home(home, themes_content=None, filename="themes.toml", cfgdir=None,
               config_content=None, keep=False):
    if not keep and os.path.isdir(home):
        shutil.rmtree(home)
    cfg = cfgdir or os.path.join(home, ".config", "tui-journal")
    os.makedirs(cfg, exist_ok=True)
    if themes_content is not None:
        with open(os.path.join(cfg, filename), "w") as f:
            f.write(themes_content)
    if config_content is not None:
        with open(os.path.join(cfg, "config.toml"), "w") as f:
            f.write(config_content)
    return cfg


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--sess", required=True)
    ap.add_argument("--home", required=True)
    ap.add_argument("--themes")          # path to file whose contents to install
    ap.add_argument("--themes-name", default="themes.toml")
    ap.add_argument("--cols", type=int, default=120)
    ap.add_argument("--rows", type=int, default=40)
    ap.add_argument("--args", default="")
    ap.add_argument("--esc", action="store_true")
    ap.add_argument("keys", nargs="*")
    o = ap.parse_args()

    content = None
    if o.themes:
        content = open(o.themes).read()
    cfg = setup_home(o.home, content, o.themes_name)
    t = Tj(home=o.home, cols=o.cols, rows=o.rows, args=o.args, sess=o.sess, fresh=False,
           env={"XDG_CONFIG_HOME": os.path.join(o.home, ".config")})
    n = 0
    for k in o.keys:
        if k in ("@cap", "@capE"):
            n += 1
            print(f"===== CAPTURE {n} =====")
            print(t.cap(esc=(k == "@capE") or o.esc))
            print(f"===== /CAPTURE {n} =====")
        elif k.startswith("@s"):
            time.sleep(float(k[2:]))
        else:
            t.send(k)
    n += 1
    print(f"===== CAPTURE {n} (final) =====")
    print(t.cap(esc=o.esc))
    print(f"===== /CAPTURE {n} =====")
    t.kill()


if __name__ == "__main__":
    main()
#!/usr/bin/env python3
"""SGR-aware screen parser: locate the editor cursor + selection from a `capture-pane -e`."""
import re

SGR_RE = re.compile(r"\x1b\[([0-9;]*)m")


def parse_line(line):
    """-> list of (char, fg, bg, bold) cells"""
    cells = []
    fg = bg = None
    bold = False
    i = 0
    while i < len(line):
        m = SGR_RE.match(line, i)
        if m:
            params = m.group(1)
            toks = params.split(";") if params else ["0"]
            j = 0
            while j < len(toks):
                t = toks[j]
                if t == "" or t == "0":
                    fg = bg = None; bold = False
                elif t == "1":
                    bold = True
                elif t == "22":
                    bold = False
                elif t == "39":
                    fg = None
                elif t == "49":
                    bg = None
                elif t == "38":
                    if j + 1 < len(toks) and toks[j+1] == "5":
                        fg = "c" + toks[j+2]; j += 2
                    elif j + 1 < len(toks) and toks[j+1] == "2":
                        fg = "rgb(%s,%s,%s)" % (toks[j+2], toks[j+3], toks[j+4]); j += 4
                elif t == "48":
                    if j + 1 < len(toks) and toks[j+1] == "5":
                        bg = "c" + toks[j+2]; j += 2
                    elif j + 1 < len(toks) and toks[j+1] == "2":
                        bg = "rgb(%s,%s,%s)" % (toks[j+2], toks[j+3], toks[j+4]); j += 4
                elif t.isdigit() and 30 <= int(t) <= 37:
                    fg = "b" + t
                elif t.isdigit() and 40 <= int(t) <= 47:
                    bg = "b" + t
                elif t.isdigit() and 90 <= int(t) <= 97:
                    fg = "B" + t
                elif t.isdigit() and 100 <= int(t) <= 107:
                    bg = "B" + t
                j += 1
            i = m.end()
            continue
        cells.append((line[i], fg, bg, bold))
        i += 1
    return cells


CURSOR_BG = {"c15": "NORMAL", "c10": "INSERT", "c4": "VISUAL",
             "c7": "NORMAL?", "c12": "listsel"}


def annotate(capE, mark_bgs=("c15", "c10", "c4")):
    """Return plain screen with a '|' marker line under cursor cells."""
    out = []
    for row in capE.split("\n"):
        cells = parse_line(row)
        text = "".join(c[0] for c in cells)
        marks = ["".join("^" if c[2] == b else " " for c in cells) for b in mark_bgs]
        out.append(text)
        for b, mk in zip(mark_bgs, marks):
            if mk.strip():
                out.append(mk.rstrip() + "   <== bg=%s (%s)" % (b, CURSOR_BG.get(b, "?")))
    return "\n".join(out)


def cursor_cells(capE, bgs=("c15", "c10", "c4")):
    res = []
    for y, row in enumerate(capE.split("\n")):
        for x, c in enumerate(parse_line(row)):
            if c[2] in bgs:
                res.append((y, x, c[0], c[2]))
    return res


if __name__ == "__main__":
    import sys
    print(annotate(sys.stdin.read()))
